function l(a){return[{key:"manufacturer",label:"Fabricante",required:!0,placeholder:"ex.: Cisco, Furukawa, Ubiquiti"},{key:"model",label:"Modelo",required:!0,placeholder:"ex.: Catalyst 9200-48P"},{key:"part_number",label:"Part number",mono:!0},{key:"u_height",label:"Altura (U)",placeholder:"1",hint:"0 = não ocupa U (tomada, AP, ONT). Aceita 0,5."},{key:"default_role_id",label:"Função padrão",type:"select",options:a.map(e=>({value:e.id,label:e.name}))},{key:"is_full_depth",label:"Profundidade total (ocupa frente e traseira do rack)",type:"check",full:!0},{key:"description",label:"Descrição",full:!0},{key:"comments",label:"Observações",type:"textarea"}]}export{l as t};
